import json,sys,re

PAT = re.compile(r'upgrad|deep_s3|deep_s4|postedit|post-edit|FWD_PIPE|SUBTILE|P1-epilogue|P1.epilogue|roofline|1\.49|4\.02|2\.05|BUG-04|prebuilt|optimizer-max|gate-hardening|C0 emitter|_dectc_codegen|DW_STAGE|FWD_STAGES|TODO|open queue|revert|keep ', re.I)

def text_of(msg):
    content = msg.get('content','')
    out=[]
    if isinstance(content,list):
        for c in content:
            if not isinstance(c,dict): continue
            t=c.get('type')
            if t=='text': out.append(('TEXT',c.get('text','')))
            elif t=='tool_use':
                name=c.get('name','')
                inp=c.get('input',{})
                # summarize input
                s=json.dumps(inp)[:1200]
                out.append(('TOOL_USE:'+name, s))
            elif t=='tool_result':
                rc=c.get('content','')
                if isinstance(rc,list):
                    rc=' '.join(x.get('text','') for x in rc if isinstance(x,dict))
                out.append(('TOOL_RESULT', str(rc)))
    else:
        out.append(('RAW',str(content)))
    return out

def main():
    f=sys.argv[1]
    window = int(sys.argv[2]) if len(sys.argv)>2 else 200
    with open(f) as fh:
        for i,line in enumerate(fh):
            try: o=json.loads(line)
            except: continue
            msg=o.get('message',{})
            if not msg:
                # toolUseResult at top level sometimes
                continue
            for kind,txt in text_of(msg):
                if PAT.search(txt):
                    for m in PAT.finditer(txt):
                        s=max(0,m.start()-window); e=min(len(txt),m.end()+window)
                        seg=txt[s:e].replace('\n',' ')
                        print(f"[L{i}][{kind}] ...{seg}...")
main()
